import unittest
from solution import solve

class Acceptance(unittest.TestCase):
    def test_empty(self): self.assertEqual(solve([]), [])
    def test_overlap(self): self.assertEqual(solve([[5,9],[1,3],[2,6]]), [[1,9]])
    def test_touch(self): self.assertEqual(solve([[1,2],[2,4]]), [[1,4]])
    def test_adjacent(self): self.assertEqual(solve([[1,2],[3,4]]), [[1,2],[3,4]])
    def test_nested(self): self.assertEqual(solve([[1,8],[2,4],[1,8]]), [[1,8]])
    def test_negative(self): self.assertEqual(solve([[-4,-1],[-2,2],[5,5]]), [[-4,2],[5,5]])
    def test_input_unchanged(self):
        data=[[5,6],[1,3]]; solve(data); self.assertEqual(data, [[5,6],[1,3]])
    def test_invalid(self):
        for value in ([[3,1]], [[1]], [[1,2,3]], [[True,2]], [['1',2]], [[1.1,2]]):
            with self.subTest(value=value), self.assertRaises(ValueError): solve(value)
    def test_tuple(self): self.assertEqual(solve([(2,4),(0,1)]), [[0,1],[2,4]])

if __name__ == "__main__": unittest.main()
